    /// The half of `validateUserInterfaceItem` this file owns. nil means "not
    /// mine" and leaves the base file's answer alone.
    func validateTimelineAction(_ action: Selector) -> Bool? {
        guard let document = document else { return false }
        let hasSelection = !document.selection.isEmpty
        switch action {
        case #selector(duplicateClips(_:)), #selector(detachAudio(_:)):
            return hasSelection
        case #selector(attachAudio(_:)):
            return selectedClips.contains { $0.linked != nil }
        case #selector(deleteClips(_:)):
            // ⌫ lifts the in/out range with nothing selected, so the item
            // has to be live for that too.
            //
            // And it has to be DEAD while text is being edited, which is
            // the guard AppDelegate's comment on this item asks for and
            // which nothing supplied before: "\u{8}" is a modifier-less key
            // equivalent, AppKit resolves those ahead of the first
            // responder, and a live item therefore eats the Delete key in
            // the timecode field, an inline rename and a text clip alike.
            // The same test `handleEditorKey` opens with.
            if view.window?.firstResponder is NSText { return false }
            // And dead while the curve plot holds a selected point, whose ⌫
            // deletes the point (spec §11 GR-12).
            if (view.window?.firstResponder as? CurveEditorView)?.holdsDeleteKey == true {
                return false
            }
            if transcriptHoldsWords { return true }
            return hasSelection || (document.inOutRange.map { $0.end > $0.start } ?? false)
        case #selector(showSpeedSheet(_:)):
            // `set_speed` is an ERROR on a non-media source (spec §6), so the
            // item is live only when the selection holds something it can act
            // on — the same subset `presentSpeedSheet` opens the sheet with.
            return selectedClips.contains { $0.source.hasSourceBound }
        case #selector(showSpeedRampSheet(_:)):
            // Exactly one selected clip, and a media one: `add_speed_ramp`
            // edits one clip and is an error on any other source (spec §11
            // SR-24 (a)) — `presentSpeedRampSheet`'s own test.
            return selectedClips.count == 1 && selectedClips[0].source.hasSourceBound
        case #selector(rippleDeleteClips(_:)):
            // The same guard as Delete: ⌘⌫ in a field editor is "delete to
            // the start of the line", not a ripple delete of the selection —
            // and the selected clip is the one whose rename field is open.
            if view.window?.firstResponder is NSText { return false }
            if transcriptHoldsWords { return true }
            return hasSelection || (document.inOutRange.map { $0.end > $0.start } ?? false)
        case #selector(trimStartToPlayhead(_:)), #selector(trimEndToPlayhead(_:)),
            #selector(freezeFrame(_:)):
            return !clipsUnderPlayhead.isEmpty
        case #selector(splitAtPlayhead(_:)):
            return !document.editedProject.snapshot.clips.isEmpty
        case #selector(removeTrack(_:)), #selector(toggleTrackHidden(_:)),
            #selector(toggleTrackMuted(_:)), #selector(toggleTrackLocked(_:)):
            return currentTrack != nil
        case #selector(nextMarker(_:)), #selector(previousMarker(_:)):
            return !document.project.snapshot.markers.isEmpty
        default:
            return nil
        }
    }
}
    /// The half of `validateUserInterfaceItem` this file owns. nil means "not
    /// mine" and leaves the base file's answer alone.
    func validateClipboardAction(
        _ action: Selector, pasteboard: NSPasteboard = .general
    ) -> Bool? {
        guard let document = document else { return false }
        switch action {
        case #selector(cut(_:)), #selector(copy(_:)):
            return !document.selection.isEmpty
        case #selector(paste(_:)):
            return canPasteClips(on: pasteboard)
        case #selector(pasteAttributes(_:)):
            // Paste needs no selection (the clips land at the playhead);
            // Paste Attributes needs something to paste ONTO.
            return canPasteClips(on: pasteboard) && !document.selection.isEmpty
        case #selector(pasteGraphicProperties(_:)):
            // Something of ours to read and a graphic to paste onto. WHAT was
            // copied is not read here (the bytes, on every menu validation):
            // a copied clip that is not a graphic is the item's beep (G-32).
            return canPasteClips(on: pasteboard)
                && selectedClips.contains { $0.source == .graphic && $0.graphic != nil }
        default:
            return nil
        }
    }
}
    /// The half of `validateUserInterfaceItem` this file owns. nil means "not
    /// mine" and leaves the other answers alone.
    func validateIdentityAction(
        _ action: Selector, item: any NSValidatedUserInterfaceItem
    ) -> Bool? {
        guard let document = document else { return false }
        switch action {
        case #selector(renameClip(_:)):
            return !document.selection.isEmpty
        case #selector(setClipLabel(_:)):
            if let menuItem = item as? NSMenuItem {
                let labels = ClipLabel.allCases
                let tagged: String? =
                    labels.indices.contains(menuItem.tag) ? labels[menuItem.tag].rawValue : nil
                menuItem.state = sharedClipLabel == .some(tagged) ? .on : .off
            }
            return !document.selection.isEmpty
        case #selector(toggleTrackSolo(_:)):
            // A checkmark, unlike its three siblings: solo is a mixing state
            // the ear cannot always confirm — a soloed track with nothing on
            // it still silences the rest — so the menu says which it is.
            let track = currentTrack
            (item as? NSMenuItem)?.state = track?.solo == true ? .on : .off
            return track != nil
        case #selector(setTrackMatte(_:)):
            // Track ▸ Matte's rows (spec §11 MT-7): the current track's mode
            // checked, by the row's tag.
            let track = currentTrack
            if let menuItem = item as? NSMenuItem {
                let modes = TrackMatte.allCases
                menuItem.state =
                    modes.indices.contains(menuItem.tag) && track?.matte == modes[menuItem.tag]
                    ? .on : .off
            }
            return track != nil
        case #selector(showTrackMix(_:)):
            return currentTrack != nil
        default:
            return nil
        }
    }
}
